CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,username TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('GUEST','FRONTDESK')));
CREATE TABLE IF NOT EXISTS room_types(id INTEGER PRIMARY KEY,name TEXT NOT NULL,description TEXT NOT NULL,capacity INTEGER NOT NULL CHECK(capacity>0),nightly_price_cents INTEGER NOT NULL CHECK(nightly_price_cents>0));
CREATE TABLE IF NOT EXISTS rooms(id INTEGER PRIMARY KEY,room_number TEXT NOT NULL UNIQUE,room_type_id INTEGER NOT NULL REFERENCES room_types(id),cleaning_status TEXT NOT NULL CHECK(cleaning_status IN ('CLEAN','DIRTY')));
CREATE TABLE IF NOT EXISTS inventory_days(room_type_id INTEGER NOT NULL REFERENCES room_types(id),stay_date TEXT NOT NULL,total INTEGER NOT NULL CHECK(total>=0),reserved INTEGER NOT NULL CHECK(reserved>=0 AND reserved<=total),PRIMARY KEY(room_type_id,stay_date));
CREATE TABLE IF NOT EXISTS orders(id INTEGER PRIMARY KEY AUTOINCREMENT,order_no TEXT NOT NULL UNIQUE,user_id INTEGER NOT NULL REFERENCES users(id),room_type_id INTEGER NOT NULL REFERENCES room_types(id),check_in_date TEXT NOT NULL,check_out_date TEXT NOT NULL CHECK(check_out_date>check_in_date),guest_count INTEGER NOT NULL CHECK(guest_count>0),price_snapshot_cents INTEGER NOT NULL CHECK(price_snapshot_cents>0),total_cents INTEGER NOT NULL CHECK(total_cents>0),status TEXT NOT NULL CHECK(status IN ('CONFIRMED','CANCELLED','NO_SHOW','CHECKED_IN','COMPLETED')),idempotency_key TEXT NOT NULL,request_hash TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(user_id,idempotency_key));
CREATE TABLE IF NOT EXISTS order_nights(order_id INTEGER NOT NULL REFERENCES orders(id),stay_date TEXT NOT NULL,allocation_status TEXT NOT NULL CHECK(allocation_status IN ('HELD','RELEASED')),PRIMARY KEY(order_id,stay_date));
CREATE TABLE IF NOT EXISTS check_in_records(id INTEGER PRIMARY KEY AUTOINCREMENT,order_id INTEGER NOT NULL UNIQUE REFERENCES orders(id),room_id INTEGER NOT NULL REFERENCES rooms(id),guest_name TEXT NOT NULL,guest_phone TEXT NOT NULL,checked_in_at TEXT NOT NULL,checked_out_at TEXT);
CREATE TABLE IF NOT EXISTS order_events(id INTEGER PRIMARY KEY AUTOINCREMENT,order_id INTEGER NOT NULL REFERENCES orders(id),operator_id INTEGER NOT NULL REFERENCES users(id),from_status TEXT CHECK(from_status IS NULL OR from_status IN ('CONFIRMED','CANCELLED','NO_SHOW','CHECKED_IN','COMPLETED')),to_status TEXT NOT NULL CHECK(to_status IN ('CONFIRMED','CANCELLED','NO_SHOW','CHECKED_IN','COMPLETED')),reason TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS one_occupied_stay_per_room ON check_in_records(room_id) WHERE checked_out_at IS NULL;
CREATE INDEX IF NOT EXISTS orders_owner_sort ON orders(user_id,created_at DESC,id DESC);
CREATE INDEX IF NOT EXISTS orders_filter ON orders(status,check_in_date,created_at DESC,id DESC);
CREATE INDEX IF NOT EXISTS stays_room ON check_in_records(room_id,checked_out_at);
CREATE INDEX IF NOT EXISTS order_events_order ON order_events(order_id,id);
